from __future__ import annotations

from pathlib import Path
import ast
import base64
import gzip
import hashlib
import os
import py_compile

EXPECTED_NORMALIZED_SHA = {'wa_backend/models.py': 'ba29f2a4160ed9feed2c7fa0c605d7f9be941be3', 'wa_backend/services.py': '3fe464506d16e879affba498759e7add886d5b50', 'wa_backend/api/warehouse.py': 'b8c642ef54ef089a19fc2380f291846386d65999'}
NEW_NORMALIZED_SHA = {'wa_backend/models.py': '55d032fd69ee202093761dce45ca35e01137a117', 'wa_backend/services.py': 'ea0e91d9d800ff44d5b69ea4f5d1ceea1238ef35', 'wa_backend/api/warehouse.py': '65ee55daf436789fe1f6643c3f63eefacd5c372d'}
PAYLOADS = {'wa_backend/models.py': '', 'wa_backend/services.py': '', 'wa_backend/api/warehouse.py': ''}


def normalize_newlines(data: bytes) -> bytes:
    return data.replace(b"\r\n", b"\n").replace(b"\r", b"\n")


def git_blob_sha(data: bytes) -> str:
    return hashlib.sha1(
        f"blob {len(data)}\0".encode("ascii") + data
    ).hexdigest()


def decode_payload(value: str) -> bytes:
    return gzip.decompress(base64.b64decode(value.encode("ascii")))


def main() -> None:
    originals = {}
    newline_styles = {}
    prepared = {}

    # تحقق من الثلاثة أولاً. إذا اختلف واحد لا نلمس أي ملف.
    for rel, expected_sha in EXPECTED_NORMALIZED_SHA.items():
        path = Path(rel)
        if not path.is_file():
            raise SystemExit(f"ERROR: الملف غير موجود: {rel}")

        raw = path.read_bytes()
        current = git_blob_sha(normalize_newlines(raw))
        if current != expected_sha:
            raise SystemExit(
                f"ERROR: {rel} مختلف عن النسخة التي بُني عليها Hardening V2.\n"
                f"Expected normalized SHA: {expected_sha}\n"
                f"Current  normalized SHA: {current}\n"
                "لم يتم تعديل أي ملف."
            )

        originals[rel] = raw
        newline_styles[rel] = "CRLF" if b"\r\n" in raw else "LF"

    # فك وتجهيز النسخ الجديدة في الذاكرة.
    for rel, payload in PAYLOADS.items():
        normalized = decode_payload(payload)
        if git_blob_sha(normalized) != NEW_NORMALIZED_SHA[rel]:
            raise SystemExit(f"ERROR: payload داخلي تالف: {rel}")
        ast.parse(normalized.decode("utf-8"), filename=rel)
        prepared[rel] = normalized

    services_text = prepared["wa_backend/services.py"].decode("utf-8")
    warehouse_text = prepared["wa_backend/api/warehouse.py"].decode("utf-8")
    models_text = prepared["wa_backend/models.py"].decode("utf-8")

    # حماية من إسقاط تحسينات services.py الأحدث بالخطأ.
    current_service_guards = (
        "_STOCKTAKE_ONLY_REFERENCE_TYPES",
        "notes لا تقبل محرف NUL.",
        "latest_attempt.submitted_at",
        "Snapshot الجرد الدوري يحتوي صنفاً خارج نطاق الجلسة.",
        "_bulk_ensure_inventory_balances",
        "نوع موقع جلسة الجرد لا يطابق نوع الجرد المعتمد.",
    )
    for token in current_service_guards:
        if token not in services_text:
            raise SystemExit(
                f"ERROR: Hardening V2 أسقط حماية موجودة مسبقاً من services.py: {token}"
            )

    required_services = (
        "async def apply_inventory_movements_batch(",
        "async def allocate_fefo_inventory_batch(",
        "async def get_company_local_date(",
        "update(InventoryLock)",
    )
    for token in required_services:
        if token not in services_text:
            raise SystemExit(f"ERROR: services hardening ناقص: {token}")

    forbidden_warehouse = (
        "_check_fefo_override_permission",
        "latest_vehicle_route_subq",
        "Role, Permission, UserRole, role_permissions",
    )
    for token in forbidden_warehouse:
        if token in warehouse_text:
            raise SystemExit(
                f"ERROR: warehouse legacy/dead code ما زال موجوداً: {token}"
            )

    if "ix_dispatch_route_company_vehicle_latest" not in models_text:
        raise SystemExit(
            "ERROR: DispatchRoute latest index مفقود من models.py."
        )

    if 'جلسة الجرد لا تحتوي على أسطر قابلة للترحيل.' in services_text:
        raise SystemExit(
            "ERROR: Empty Stocktake ما زال مرفوضاً في services.py."
        )

    # تجهيز ملفات مؤقتة ثم Syntax check قبل الاستبدال.
    temp_paths = {}
    replaced = []
    try:
        for rel, normalized in prepared.items():
            path = Path(rel)
            output = normalized
            if newline_styles[rel] == "CRLF":
                output = output.replace(b"\n", b"\r\n")

            tmp = path.with_suffix(path.suffix + ".hardening_v2.tmp")
            tmp.write_bytes(output)
            temp_paths[rel] = tmp
            py_compile.compile(str(tmp), doraise=True)

        try:
            for rel in (
                "wa_backend/models.py",
                "wa_backend/services.py",
                "wa_backend/api/warehouse.py",
            ):
                os.replace(temp_paths[rel], Path(rel))
                replaced.append(rel)
        except Exception:
            # Atomic best-effort rollback لأي استبدال تم قبل الخطأ.
            for rel in replaced:
                Path(rel).write_bytes(originals[rel])
            raise

    finally:
        for tmp in temp_paths.values():
            if tmp.exists():
                tmp.unlink()

    print("WAREHOUSE_HARDENING_V2_APPLIED_OK")
    for rel in (
        "wa_backend/models.py",
        "wa_backend/services.py",
        "wa_backend/api/warehouse.py",
    ):
        raw = Path(rel).read_bytes()
        print(
            f"{rel} -> normalized SHA: "
            f"{git_blob_sha(normalize_newlines(raw))}"
        )

    print(
        "Changed: bulk movement + bulk FEFO + company-local date + "
        "stocktake lock hardening + latest vehicle lookup"
    )
    print(
        "Preserved: all hardening already present in services(20260905-173711).py"
    )
    print(
        "Next: python -m py_compile "
        "wa_backend/models.py wa_backend/services.py wa_backend/api/warehouse.py"
    )


if __name__ == "__main__":
    main()
